flash.output:
fn flash (reads q: [f32; 64, 16]) (reads kt: [f32; 16, 32])
    (reads v: [f32; 32, 16]) -> out y: [f32; 64, 16]
=
  grid on M4Gpu gi in 0 .. 2
      by tile (si, sj) parts [8, 16]
      writes y[gi * 32 .. gi * 32 + 32, 0 .. 16] as yt do
    var o: [f32; 32, 16] = repeat (-0.0)
    var m: [f32; 32, 1] = repeat (from_bits (4286578688 as u32))
    var l: [f32; 32, 1] = repeat (-0.0)
    for gj in 0 .. 4 do
      var s: [f32; 32, 8] = repeat (-0.0)
      for gc in 0 .. 1 do
        let x: [f32; 32, 16] =
          load q[gi * 32 .. gi * 32 + 32, gc * 16 .. gc * 16 + 16]
        let k: [f32; 16, 8] =
          load kt[gc * 16 .. gc * 16 + 16, gj * 8 .. gj * 8 + 8]
        s = mma x k s
      let m2: [f32; 32, 1] = max m (reduce Max f32 over cols by halving do s)
      let e: [f32; 32, 8] = exp (s - m2)
      let alpha: [f32; 32, 1] = rescale m m2
      l = l * alpha + (reduce Sum f32 over cols by order do e)
      let w: [f32; 8, 16] = load v[gj * 8 .. gj * 8 + 8, 0 .. 16]
      o = o * alpha
      o = mma e w o
      m = m2
    store yt = o / l
